-- Human-verified service provider directory. No availability, pricing, rating, or endorsement is inferred.
-- Review before applying. This file does not run against an environment by itself.
begin;
create table public.service_provider_profiles(
 id uuid primary key default gen_random_uuid(),company_id uuid not null,provider_name text not null check(char_length(provider_name)between 2 and 200),
 category text not null check(category in('roadside','towing','truck_repair','trailer_repair','reefer_repair','cross_dock','forklift','washout','parking','insurance','factoring','accounting','other')),
 phone text,email text,website text,address_line text,city text,state text check(state is null or state~'^[A-Z]{2}$'),postal_code text,
 service_area text,availability_note text,status text not null default'active'check(status in('active','inactive')),
 factual_note text not null check(char_length(factual_note)between 3 and 2000),verified_by uuid not null,request_id text not null,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,id),unique(company_id,request_id)
);
create table public.service_provider_events(
 id uuid primary key default gen_random_uuid(),company_id uuid not null,provider_id uuid not null,event_type text not null check(event_type in('created','updated','status_changed')),
 before_state jsonb,after_state jsonb,factual_note text not null,actor_user_id uuid not null,request_id text not null,created_at timestamptz not null default now(),
 unique(company_id,request_id),constraint service_provider_event_company_fk foreign key(company_id,provider_id)references public.service_provider_profiles(company_id,id)
);
create index service_provider_company_category_idx on public.service_provider_profiles(company_id,category,status,provider_name);
alter table public.service_provider_profiles enable row level security;alter table public.service_provider_events enable row level security;
create policy service_provider_company_select on public.service_provider_profiles for select using(company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting'));
create policy service_provider_events_company_select on public.service_provider_events for select using(company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting'));
revoke all privileges on table public.service_provider_profiles,public.service_provider_events from public,anon,authenticated,service_role;
grant select on table public.service_provider_profiles,public.service_provider_events to authenticated,service_role;grant insert,update on table public.service_provider_profiles to service_role;grant insert on table public.service_provider_events to service_role;
create or replace function public.list_verified_service_providers()returns table(id uuid,provider_name text,category text,phone text,email text,website text,address_line text,city text,state text,postal_code text,service_area text,availability_note text,status text,factual_note text,updated_at timestamptz)
language sql stable security definer set search_path=public as $$select p.id,p.provider_name,p.category,p.phone,p.email,p.website,p.address_line,p.city,p.state,p.postal_code,p.service_area,p.availability_note,p.status,p.factual_note,p.updated_at from public.service_provider_profiles p where p.company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','dispatcher','safety','accounting')order by case when p.status='active'then 0 else 1 end,p.category,p.provider_name$$;
create or replace function public.save_verified_service_provider(p_provider_id uuid,p_provider_name text,p_category text,p_phone text,p_email text,p_website text,p_address_line text,p_city text,p_state text,p_postal_code text,p_service_area text,p_availability_note text,p_status text,p_note text,p_request_id text)returns uuid
language plpgsql security definer set search_path=public as $$declare c uuid:=public.document_intake_company_id();u uuid:=auth.uid();r text:=public.current_business_role();x uuid;b jsonb;a jsonb;e text;begin if c is null or u is null or r not in('super_admin','owner','dispatcher','safety','accounting')then raise exception'Not authorized';end if;if p_request_id is null or char_length(p_request_id)not between 8 and 200 or char_length(trim(p_provider_name))not between 2 and 200 or p_category not in('roadside','towing','truck_repair','trailer_repair','reefer_repair','cross_dock','forklift','washout','parking','insurance','factoring','accounting','other')or p_status not in('active','inactive')or char_length(trim(p_note))not between 3 and 2000 or(coalesce(trim(p_phone),'')=''and coalesce(trim(p_email),'')=''and coalesce(trim(p_address_line),'')='')or(p_email is not null and trim(p_email)<>''and(p_email!~*'^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'or char_length(p_email)>254))or(p_state is not null and trim(p_state)<>''and upper(trim(p_state))!~'^[A-Z]{2}$')or(p_website is not null and trim(p_website)<>''and p_website!~*'^https://')then raise exception'Invalid provider facts';end if;select provider_id into x from public.service_provider_events where company_id=c and request_id=p_request_id;if x is not null then return x;end if;if p_provider_id is null then insert into public.service_provider_profiles(company_id,provider_name,category,phone,email,website,address_line,city,state,postal_code,service_area,availability_note,status,factual_note,verified_by,request_id)values(c,trim(p_provider_name),p_category,nullif(trim(p_phone),''),nullif(lower(trim(p_email)),''),nullif(trim(p_website),''),nullif(trim(p_address_line),''),nullif(trim(p_city),''),nullif(upper(trim(p_state)),''),nullif(trim(p_postal_code),''),nullif(trim(p_service_area),''),nullif(trim(p_availability_note),''),p_status,trim(p_note),u,p_request_id)returning id into x;e:='created';else select to_jsonb(v)into b from public.service_provider_profiles v where v.company_id=c and v.id=p_provider_id for update;if b is null then raise exception'Provider not found';end if;update public.service_provider_profiles set provider_name=trim(p_provider_name),category=p_category,phone=nullif(trim(p_phone),''),email=nullif(lower(trim(p_email)),''),website=nullif(trim(p_website),''),address_line=nullif(trim(p_address_line),''),city=nullif(trim(p_city),''),state=nullif(upper(trim(p_state)),''),postal_code=nullif(trim(p_postal_code),''),service_area=nullif(trim(p_service_area),''),availability_note=nullif(trim(p_availability_note),''),status=p_status,factual_note=trim(p_note),verified_by=u,request_id=p_request_id,updated_at=now()where company_id=c and id=p_provider_id returning id into x;e:=case when b->>'status'<>p_status then'status_changed'else'updated'end;end if;select to_jsonb(v)into a from public.service_provider_profiles v where v.company_id=c and v.id=x;insert into public.service_provider_events(company_id,provider_id,event_type,before_state,after_state,factual_note,actor_user_id,request_id)values(c,x,e,b,a,trim(p_note),u,p_request_id);return x;end$$;
revoke all on function public.list_verified_service_providers(),public.save_verified_service_provider(uuid,text,text,text,text,text,text,text,text,text,text,text,text,text,text)from public,anon;grant execute on function public.list_verified_service_providers(),public.save_verified_service_provider(uuid,text,text,text,text,text,text,text,text,text,text,text,text,text,text)to authenticated;
commit;
